341	impl Connection {
342	    /// Register a callback function to be invoked whenever
343	    /// a transaction is committed.
344	    ///
345	    /// The callback returns `true` to rollback.
346	    ///
347	    /// This hook shares its registration with
348	    /// [`try_commit_hook`](Connection::try_commit_hook): the most recently
349	    /// registered hook wins, and unregistering either one removes the
350	    /// currently registered hook.
351	    #[inline]
352	    pub fn commit_hook<F>(&mut self, hook: Option<F>) -> Result<()>
353	    where
354	        F: FnMut() -> bool + Send + 'static,
355	    {
356	        self.db.borrow_mut().commit_hook(hook)
357	    }
358	
359	    /// Register a callback function to be invoked whenever
360	    /// a transaction is committed, with the ability to report
361	    /// why a commit was rejected.
362	    ///
363	    /// The callback returns `Ok(false)` to let the commit proceed, `Ok(true)`
364	    /// to roll it back (producing the same error as a
365	    /// [`commit_hook`](Connection::commit_hook) rejection), or `Err(e)` to
366	    /// roll it back and have the call that triggered the commit fail with
367	    /// `e`. If the callback panics, the commit is rolled back and the
368	    /// triggering call fails with [`Error::UnwindingPanic`].
369	    ///
370	    /// This hook shares its registration with
371	    /// [`commit_hook`](Connection::commit_hook): the most recently registered
372	    /// hook wins, and unregistering either one removes the currently
373	    /// registered hook. A rejected commit does not unregister the hook.
374	    #[inline]
375	    pub fn try_commit_hook<F>(&mut self, hook: Option<F>) -> Result<()>
376	    where
377	        F: FnMut() -> Result<bool> + Send + 'static,
378	    {
379	        self.db.borrow_mut().try_commit_hook(hook)
380	    }
381	
382	    /// Register a callback function to be invoked whenever
383	    /// a transaction is rolled back.
384	    #[inline]
385	    pub fn rollback_hook<F>(&mut self, hook: Option<F>) -> Result<()>
386	    where
387	        F: FnMut() + Send + 'static,
388	    {
389	        self.db.borrow_mut().rollback_hook(hook)
390	    }
391	
392	    /// Register a callback function to be invoked whenever
393	    /// a row is updated, inserted or deleted in a rowid table.
394	    ///
395	    /// The callback parameters are:
396	    ///
397	    /// - the type of database update (`SQLITE_INSERT`, `SQLITE_UPDATE` or
398	    ///   `SQLITE_DELETE`),
399	    /// - the name of the database ("main", "temp", ...),
400	    /// - the name of the table that is updated,
401	    /// - the ROWID of the row that is updated.
402	    #[inline]
403	    pub fn update_hook<F>(&mut self, hook: Option<F>) -> Result<()>
404	    where
405	        F: FnMut(Action, &str, &str, i64) + Send + 'static,
406	    {
407	        self.db.borrow_mut().update_hook(hook)
408	    }
409	
410	    /// Register a callback that is invoked each time data is committed to a database in wal mode.
411	    ///
412	    /// A single database handle may have at most a single write-ahead log callback registered at one time.
413	    /// Calling `wal_hook` replaces any previously registered write-ahead log callback.
414	    /// Note that the `sqlite3_wal_autocheckpoint()` interface and the `wal_autocheckpoint` pragma
415	    /// both invoke `sqlite3_wal_hook()` and will overwrite any prior `sqlite3_wal_hook()` settings.
416	    pub fn wal_hook<F>(&mut self, hook: Option<F>) -> Result<()>
417	    where
418	        F: FnMut(&Wal, c_int) -> Result<()> + Send + 'static,
419	    {
420	        unsafe extern "C" fn wal_hook_callback<F>(
421	            client_data: *mut c_void,
422	            db: *mut ffi::sqlite3,
423	            db_name: *const c_char,
424	            pages: c_int,
425	        ) -> c_int
426	        where
427	            F: FnMut(&Wal, c_int) -> Result<()>,
428	        {
429	            unsafe {
430	                let wal = Wal { db, db_name };
431	                catch_unwind(|| {
432	                    let hook_fn: *mut F = client_data.cast::<F>();
433	                    match (*hook_fn)(&wal, pages) {
434	                        Ok(()) => ffi::SQLITE_OK,
435	                        Err(e) => e
436	                            .sqlite_error()
437	                            .map_or(ffi::SQLITE_ERROR, |x| x.extended_code),
438	                    }
439	                })
440	                .unwrap_or_default()
441	            }
442	        }
443	        let x = hook.as_ref().map(|_| wal_hook_callback::<F> as _);
444	        let mut c = self.db.borrow_mut();
445	        c.set_clientdata(c"sqlite3_wal_hook", hook, |db, bh| unsafe {
446	            ffi::sqlite3_wal_hook(db, x, bh);
447	            ffi::SQLITE_OK
448	        })?;
449	        Ok(())
450	    }
