534	/// The commit hook registered on a connection.
535	///
536	/// Both `commit_hook` and `try_commit_hook` share this single registration:
537	/// the most recent call to either entry point replaces the previous hook,
538	/// and unregistering either one removes whichever hook is current.
539	enum CommitHook {
540	    Simple(Box<dyn FnMut() -> bool + Send>),
541	    Fallible(Box<dyn FnMut() -> Result<bool> + Send>),
542	}
543	
544	struct CommitHookState {
545	    hook: CommitHook,
546	    /// The reason the fallible hook rejected the most recent commit attempt,
547	    /// to be reported by the call that observes SQLite's
548	    /// `SQLITE_CONSTRAINT_COMMITHOOK` error. Reset on every hook invocation,
549	    /// so a stale reason can never be attributed to a later failure.
550	    error: Option<Error>,
551	}
552	
553	unsafe extern "C" fn commit_hook_callback(p_arg: *mut c_void) -> c_int {
554	    unsafe {
555	        let state: *mut CommitHookState = p_arg.cast();
556	        match &mut (*state).hook {
557	            CommitHook::Simple(hook) => {
558	                let r = catch_unwind(AssertUnwindSafe(hook));
559	                c_int::from(r.unwrap_or_default())
560	            }
561	            CommitHook::Fallible(hook) => {
562	                let r = catch_unwind(AssertUnwindSafe(hook));
563	                let (rollback, error) = match r {
564	                    Ok(Ok(rollback)) => (rollback, None),
565	                    Ok(Err(err)) => (true, Some(err)),
566	                    Err(_) => (true, Some(Error::UnwindingPanic)),
567	                };
568	                (*state).error = error;
569	                c_int::from(rollback)
570	            }
571	        }
572	    }
573	}
574	
575	/// If `code` reports that the commit hook on `db` rejected a commit
576	/// (`SQLITE_CONSTRAINT_COMMITHOOK`) and the currently registered fallible
577	/// hook provided a reason, take and return it. The reason is consumed, so it
578	/// is reported at most once, by the first call that observes the rejection.
579	pub(crate) unsafe fn take_try_commit_hook_error(
580	    db: *mut ffi::sqlite3,
581	    code: c_int,
582	) -> Option<Error> {
583	    if db.is_null()
584	        || (code != ffi::SQLITE_CONSTRAINT_COMMITHOOK
585	            && ((code & 0xff) != ffi::SQLITE_CONSTRAINT
586	                || unsafe { ffi::sqlite3_extended_errcode(db) }
587	                    != ffi::SQLITE_CONSTRAINT_COMMITHOOK))
588	    {
589	        return None;
590	    }
591	    let state = unsafe { ffi::sqlite3_get_clientdata(db, c"sqlite3_commit_hook".as_ptr()) }
592	        .cast::<CommitHookState>();
593	    if state.is_null() {
594	        return None;
595	    }
596	    unsafe { (*state).error.take() }
597	}
