/// The wal hook registered on a connection, plus the reason its most recent
/// notification failed, to be reported by the call that observes SQLite's
/// generic `SQLITE_ERROR`. Reset on every hook invocation, so a stale reason
/// can never be attributed to a later failure.
struct WalHookState {
    hook: Box<dyn FnMut(&Wal, c_int) -> Result<()> + Send>,
    error: Option<Error>,
}

unsafe extern "C" fn wal_hook_callback(
    client_data: *mut c_void,
    db: *mut ffi::sqlite3,
    db_name: *const c_char,
    pages: c_int,
) -> c_int {
    unsafe {
        let state: *mut WalHookState = client_data.cast();
        let wal = Wal { db, db_name };
        (*state).error = None;
        match catch_unwind(AssertUnwindSafe(|| ((*state).hook)(&wal, pages))) {
            Ok(Ok(())) => ffi::SQLITE_OK,
            Ok(Err(e)) => {
                (*state).error = Some(e);
                ffi::SQLITE_ERROR
            }
            Err(_) => {
                (*state).error = Some(Error::UnwindingPanic);
                ffi::SQLITE_ERROR
            }
        }
    }
}

